// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // owner (deployer) is this test contract; it must be able to receive the transfer
    receive() external payable {}

    function testFuzz_property(uint256 balance, uint256 value) public {
        // 1. admissible domain: a funded contract and a withdrawal it can cover
        balance = bound(balance, 1, 1e30);
        value = bound(value, 0, balance);

        // 2. fund the contract, then the owner withdraws exactly `value`
        vm.deal(address(c), balance);
        vm.prank(address(this)); // onlyOwner: owner == deployer == this test contract
        c.withdraw(value);

        // 3. general rule: withdrawing v from a balance of B leaves exactly B - v
        assertTrue(address(c).balance == balance - value);
    }
}
